package com.jobmatcher.controller;import com.jobmatcher.model.JobApplication;import com.jobmatcher.repository.ApplicationRepository;import com.jobmatcher.service.JobService;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/applications") public class ApplicationController {private final ApplicationRepository apps;private final JobService jobs;public ApplicationController(ApplicationRepository a,JobService j){apps=a;jobs=j;}@GetMapping public List<JobApplication> mine(java.security.Principal p){return apps.findByUserIdOrderByAppliedAtDesc(Long.valueOf(p.getName()));}@PostMapping public ResponseEntity<?> apply(@RequestBody Map<String,Long> body,java.security.Principal p){Long uid=Long.valueOf(p.getName()),jid=body.get("jobId");if(jid==null)return ResponseEntity.badRequest().body(Map.of("error","jobId is required."));JobService.Job job=jobs.all().stream().filter(j->j.id()==jid).findFirst().orElse(null);if(job==null)return ResponseEntity.badRequest().body(Map.of("error","Unknown job."));if(apps.existsByUserIdAndJobId(uid,jid))return ResponseEntity.status(409).body(Map.of("error","You have already applied for this role."));return ResponseEntity.status(201).body(apps.save(new JobApplication(uid,jid,job.title(),job.company())));}}
